using GestionProduits.Data; using GestionProduits.Models; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; namespace GestionProduits.Pages.Categories; public class DeleteModel : PageModel { private readonly AppDbContext _context; public DeleteModel(AppDbContext context) => _context = context; public Categorie Categorie { get; set; } = default!; public bool ContientProduits { get; set; } public async Task<IActionResult> OnGetAsync(int id) { Categorie = await _context.Categories.Include(c => c.Produits).FirstOrDefaultAsync(c => c.Id == id); if (Categorie == null) return NotFound(); ContientProduits = Categorie.Produits.Count > 0; return Page(); } public async Task<IActionResult> OnPostAsync(int id) { var c = await _context.Categories.Include(c => c.Produits).FirstOrDefaultAsync(c => c.Id == id); if (c == null) return NotFound(); if (c.Produits.Count > 0) { ModelState.AddModelError(string.Empty, "Cette catégorie contient encore des produits."); Categorie = c; ContientProduits = true; return Page(); } _context.Categories.Remove(c); await _context.SaveChangesAsync(); return RedirectToPage("Index"); } }
